import java.util.*;
import java.io.*;

public class Main {
    static long[] findMissing(long[] nums) {
        // Write your solution here
        // Return the two missing numbers in increasing order
        return new long[]{0, 0};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int k = (int) in.nval;
        long[] nums = new long[k];
        for (int i = 0; i < k; i++) {
            in.nextToken();
            nums[i] = (long) in.nval;
        }
        long[] res = findMissing(nums);
        System.out.println(res[0] + " " + res[1]);
    }
}
